INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('02ab4cc8-792e-4b24-88e6-07a0f6d8403c', '21feff02-016d-46e2-bb9d-c27495133b1b', '61. óra: Tengelyesen szimmetrikus háromszögek, négyszögek, sokszögek', 'Egyenlő szárú háromszög tulajdonságai és szimmetriatengelye.', 'Matematika', '6. osztály', 'Geometria, tengelyes tükrözés', '[{"id": "55d330ee-316b-484f-b8d9-04b3ed1a5203", "text": "Hány szimmetriatengelye van az egyenlő szárú (nem egyenlő oldalú) háromszögnek?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "1"}, {"id": "fceabe10-b705-4c22-b647-54c4bee7eacd", "text": "Hány szimmetriatengelye van a szabályos (egyenlő oldalú) háromszögnek?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "3"}, {"id": "97f1adc9-e9c5-46f4-9b7e-3675c7c67c88", "text": "Az egyenlő szárú háromszög alapon fekvő szögei egyenlők.", "type": "true-false", "options": [{"id": "126d28b1-5d26-4e87-b450-55cb01de8850", "text": "Igaz", "isCorrect": true}, {"id": "79c1b8e4-e8db-40e2-95f0-66847be71407", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "4de6dd01-26e3-4aa8-867f-653441175a5d", "text": "Ha az egyenlő szárú háromszög szárai 8 cm-esek, és alapja 5 cm, mennyi a kerülete? (8+8+5)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "21"}, {"id": "94bbd5dc-d8c2-4276-94c3-80165f8c93f4", "text": "Ha az egyenlő szárú háromszög szárszöge (csúcsszöge) 40°, mekkorák az alapon fekvő szögek? ((180-40)/2)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "70"}, {"id": "49f4a65e-1a20-4b56-9c2a-c0dbf1d8e810", "text": "Az egyenlő szárú háromszög szimmetriatengelye az alap felezőmerőlegese és a szárszög felezője is egyben.", "type": "true-false", "options": [{"id": "f7d1cf92-3163-4123-a80e-5d42931b5bc5", "text": "Igaz", "isCorrect": true}, {"id": "72dc02ea-17a3-409c-8320-e3f02cbebbbe", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "f5aab13a-c370-4076-a5f9-958b8288bbf6", "text": "Az egyenlő oldalú háromszög minden szöge 60°-os.", "type": "true-false", "options": [{"id": "30e27404-1870-4f47-afe5-ee99731393a6", "text": "Igaz", "isCorrect": true}, {"id": "2b30786d-13cf-4bee-bbb0-e6b7deba0608", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('3a70f860-4873-4441-8347-a8037a36447b', '21feff02-016d-46e2-bb9d-c27495133b1b', '62. óra: Tengelyesen szimmetrikus háromszögek, négyszögek, sokszögek II.', 'Tengelyesen szimmetrikus négyszögek (téglalap, négyzet, rombusz, deltoid, szimmetrikus trapéz) szimmetriatengelyei.', 'Matematika', '6. osztály', 'Geometria, tengelyes tükrözés', '[{"id": "86d4966b-e65f-4b0d-b0b4-e60004aa4b31", "text": "Hány szimmetriatengelye van a négyzetnek?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "4"}, {"id": "d2a910e1-7ab7-4793-a851-c311086623d9", "text": "Hány szimmetriatengelye van a téglalapnak (ami nem négyzet)? (az oldalfelező merőlegesek)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "2"}, {"id": "1caea799-999b-4c31-88af-0f49d605939d", "text": "Hány szimmetriatengelye van a rombusznak (ami nem négyzet)? (az átlók egyenesei)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "2"}, {"id": "8da5b8cf-e332-4d6e-978e-9c1f5d1f89a9", "text": "Hány szimmetriatengelye van a deltoidnak (ha nem rombusz)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "1"}, {"id": "99cfa79f-9595-4437-9726-2ee5338ce32a", "text": "A szimmetrikus (egyenlő szárú) trapéznak 1 szimmetriatengelye van.", "type": "true-false", "options": [{"id": "d0547790-d3b7-4675-bdfc-cc750f00f534", "text": "Igaz", "isCorrect": true}, {"id": "3e83d962-66f4-430a-8e97-b29f1300a504", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "76b9533f-8b99-437d-8e2b-572fa36c22b7", "text": "Az általános paralelogrammának (ami nem rombusz és nem téglalap) NINCS tengelyes szimmetriatengelye.", "type": "true-false", "options": [{"id": "f3e0cab7-3b78-4c53-a025-e53a78340f89", "text": "Igaz (középpontosan szimmetrikus, de tengelyesen nem)", "isCorrect": true}, {"id": "e56d7f51-941a-4899-85a4-d0bc596df5f2", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "1b2f67d3-d546-4568-83ca-ac20017d4182", "text": "Hány szimmetriatengelye van a szabályos ötszögnek?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "5"}]'::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('1a221f83-846a-4a59-9172-a4513bf5d7ce', '21feff02-016d-46e2-bb9d-c27495133b1b', '63. óra: Szerkesztési feladatok', 'Szakasz- és szögmásolás, szögfelezés, háromszögszerkesztések gyakorlása.', 'Matematika', '6. osztály', 'Geometria, tengelyes tükrözés', '[{"id": "9eb05c33-8111-4eee-a6c5-ea22827bf9a8", "text": "Hogyan felezünk meg egy 80°-os szöget szerkesztéssel?", "type": "multiple-choice", "options": [{"id": "12732348-fe43-4b45-ac9c-bcfe57f6b29d", "text": "Megszerkesztjük a szög szögfelező egyenesét, így két 40°-os szöget kapunk", "isCorrect": true}, {"id": "9edd51db-25ca-4cbe-ba94-653b63eabda5", "text": "Levágunk belőle 10 fokot", "isCorrect": false}, {"id": "fc1c7278-e3e4-431e-8268-57cd8cca2a9b", "text": "Merőlegest húzunk a szög egyik szárára", "isCorrect": false}, {"id": "625bc461-47de-490d-9ed4-843924398382", "text": "Szögmérővel elosztjuk", "isCorrect": false}], "timeLimit": 15}, {"id": "0739687f-cb17-4ad0-b61f-8be44338a03a", "text": "A szögfelezéshez körzőt és egyenes vonalzót használsz.", "type": "true-false", "options": [{"id": "53433ae6-b348-4e54-8053-2792bbb47aa9", "text": "Igaz", "isCorrect": true}, {"id": "68d16ef7-c198-4455-a8ff-ab3398177e9f", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "96395316-3fd5-4def-9b38-3ed91654dab9", "text": "Hány fokos szögeket kapunk egy 90°-os derékszög felezésekor?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "45"}, {"id": "b1793f2a-db2b-4aaf-b74a-0ef044f829e1", "text": "Hány fokos szögeket kapunk egy 180°-os egyenesszög felezésekor?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "90"}, {"id": "dffe545f-bbdd-4a9d-8dc6-e20b75350361", "text": "Szerkeszthető-e 60°-os szög kizárólag körzővel és vonalzóval (szabályos háromszög szerkesztésével)?", "type": "true-false", "options": [{"id": "5b0f15ad-addc-46a3-be6e-488bd31557b7", "text": "Igaz", "isCorrect": true}, {"id": "52e31a2b-ba69-471f-8523-b93704c0e01a", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "d5fc04fa-4b1d-49b4-8cb0-3947c4352588", "text": "Szerkeszthető-e 30°-os szög a 60°-os szög felezésével?", "type": "true-false", "options": [{"id": "a1242f66-c9df-430b-8364-84677c5337e8", "text": "Igaz", "isCorrect": true}, {"id": "f931dbcf-ba51-4d05-888d-0b77caa24b33", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "c1df6d7d-50f2-4b65-b79d-3a5ab68ce1f7", "text": "Szerkeszthető-e 15°-os szög a 30°-os szög felezésével?", "type": "true-false", "options": [{"id": "f166484a-aed9-49a3-ac23-104c110721e3", "text": "Igaz", "isCorrect": true}, {"id": "5fcfbac0-0218-4f99-9da4-0259f8f621b8", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('87284479-c2b8-49be-8583-0f7576fa4435', '21feff02-016d-46e2-bb9d-c27495133b1b', '64. óra: Dinamikus szerkesztőprogram megismerése', 'Interaktív geometriai szoftverek (GeoGebra), alakzatok mozgatása, tulajdonságok megfigyelése.', 'Matematika', '6. osztály', 'Geometria, tengelyes tükrözés', '[{"id": "7c1e2d57-c3ae-4e17-8a28-d6226bdd7a05", "text": "Mire való a GeoGebra dinamikus geometriai program?", "type": "multiple-choice", "options": [{"id": "7fde982d-4e61-4217-b06e-9d90f783ebc7", "text": "Geometriai alakzatok szerkesztésére, mozgatására, mérésére és összefüggések felfedezésére", "isCorrect": true}, {"id": "b729b38b-f6e8-4595-bfbb-d76911362aa9", "text": "Szövegszerkesztésre", "isCorrect": false}, {"id": "5632aa33-dbe9-4319-b7fc-0e9085da1076", "text": "Videóvágásra", "isCorrect": false}, {"id": "996e4231-7286-415a-a60d-cf7b4c0f9cf6", "text": "Kódolásra C++ nyelven", "isCorrect": false}], "timeLimit": 15}, {"id": "662b10ae-f646-440e-9f73-d82d89137073", "text": "Dinamikus szerkesztőprogramban az csúcsok mozgatásakor az alakzat tulajdonságai és összefüggései megőrződnek.", "type": "true-false", "options": [{"id": "f614c4a2-4b4c-4ceb-aa06-ab96fc37e4b2", "text": "Igaz", "isCorrect": true}, {"id": "e98ea4d5-8430-4477-bb9b-42b8e5e749cc", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "bfed75d9-59af-4877-a804-16c9affb0a69", "text": "A dinamikus programokban a háromszög belső szögeinek összege mozgattatás közben is mindig 180° marad.", "type": "true-false", "options": [{"id": "3d7ba8c8-b03b-4cfe-b897-6a0a616e4c5f", "text": "Igaz", "isCorrect": true}, {"id": "ec461c96-4af0-4b35-87c7-23295b872105", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "53aed3ad-aa8c-4fc2-a56f-d3a7f94a13c7", "text": "A szerkesztőprogram segítségével ellenőrizhető a kézi szerkesztések pontossága.", "type": "true-false", "options": [{"id": "90a129de-5dd7-4cba-850d-93b8c8627fb0", "text": "Igaz", "isCorrect": true}, {"id": "fc21cbda-49c9-4c25-ab02-43849d68c1f5", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "ba819e97-ffff-44d6-bc3c-2da0c31f7609", "text": "Melyik funkció segít a pontok tengelyes tükörképének azonnali előállításában a szoftverben?", "type": "multiple-choice", "options": [{"id": "174e4dbc-1a9c-45ec-9e48-faa981dc40b2", "text": "Tengelyes tükrözés eszköz", "isCorrect": true}, {"id": "d9bd164e-dc10-435b-bc2d-d41d6405dbca", "text": "Színezés", "isCorrect": false}, {"id": "5d847dce-c181-4a4c-ab61-d477a31eed7c", "text": "Törlés", "isCorrect": false}, {"id": "8214be64-5627-4926-8b8d-d204af1c1350", "text": "Nagyítás", "isCorrect": false}], "timeLimit": 15}, {"id": "a97887a5-44d3-499a-8b7e-20fc61faef08", "text": "A számítógépes geometriai modellezés segíti a mélyebb megértést.", "type": "true-false", "options": [{"id": "711c5230-b648-42a3-b20d-7175cd459624", "text": "Igaz", "isCorrect": true}, {"id": "96057f70-580e-4b3b-9c8b-f2254ffdc4a9", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "c1eb4f2f-2519-4023-84e3-da617e580a42", "text": "Hány fok a teljes szög a geometriában?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "360"}]'::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('c0fc8102-105d-4a70-a1d3-1dcbe3ecc247', '21feff02-016d-46e2-bb9d-c27495133b1b', '65. óra: Összefoglalás', 'A Geometria és tengelyes tükrözés fejezet fogalmainak, szerkesztéseinek összefoglalása.', 'Matematika', '6. osztály', 'Geometria, tengelyes tükrözés', '[{"id": "9321144a-b71f-4a7f-806a-8bee390973a7", "text": "Hány szimmetriatengelye van a téglalapnak?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "2"}, {"id": "45fd7d6e-0cb6-4f76-82b2-c307692dd2c2", "text": "Hány szimmetriatengelye van a négyzetnek?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "4"}, {"id": "ca8683ec-0c91-4061-830f-ca31fc003106", "text": "A tengelyes tükrözés megváltoztatja a síkidom körüljárási irányát.", "type": "true-false", "options": [{"id": "89d610d9-12b6-4078-be59-1c338524772e", "text": "Igaz", "isCorrect": true}, {"id": "ed1faf61-1127-415d-b71f-8837a4ed18d8", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "14ed19da-c240-43e1-9775-c665a00bab3b", "text": "Mennyi a háromszög belső szögeinek összege?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "180"}, {"id": "500b80b6-6016-4a85-a852-5487ae9eabd6", "text": "A szakaszfelező merőleges minden pontja egyenlő távolságra van a szakasz két végpontjától.", "type": "true-false", "options": [{"id": "238cd70c-7870-4d30-a05e-d346eefe652c", "text": "Igaz", "isCorrect": true}, {"id": "e2b16790-ecb9-4832-b74a-d0a80eca6bcc", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "0c8507cf-e6ac-4d25-9119-c55d6978affb", "text": "Ha a kör átmérője 12 cm, mekkora a sugara? (cm-ben)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "6"}, {"id": "5b641139-5e71-4d07-98ce-9db30cdc6c41", "text": "A szögfelező egyenes felezi a szöget és egyenlő távolságra van a szög száraitól.", "type": "true-false", "options": [{"id": "e7465116-e618-4ba8-a540-19e24479d14e", "text": "Igaz", "isCorrect": true}, {"id": "751990d6-cd16-47e8-a863-02f19790bb6a", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('8826b54c-2725-4e34-91d9-48301a4c280b', '21feff02-016d-46e2-bb9d-c27495133b1b', '66. óra: Témazáró dolgozat', 'Témazáró számonkérés a Geometria és tengelyes tükrözés fejezetből (10 kérdés).', 'Matematika', '6. osztály', 'Geometria, tengelyes tükrözés', '[{"id": "6d808bf8-817b-45cc-9935-b5866684f3e7", "text": "1. Mennyi a háromszög belső szögeinek összege?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "180"}, {"id": "0ed270ba-217b-4737-963e-c76387e3dc32", "text": "2. Mennyi a négyszög belső szögeinek összege?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "360"}, {"id": "d3be30a7-9dac-4763-b583-5f837106160b", "text": "3. Hány szimmetriatengelye van a négyzetnek?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "4"}, {"id": "d7a3e7fb-e9e8-44dd-b239-379b1da57205", "text": "4. Hány szimmetriatengelye van az egyenlő szárú (nem szabályos) háromszögnek?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "1"}, {"id": "8f33f0b4-8791-4f0a-9b85-5b05d334f81b", "text": "5. Ha a kör sugara 4,5 cm, mekkora az átmérője? (cm-ben)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "9"}, {"id": "716391b7-8697-4966-994d-c3588de4d555", "text": "6. A tengelyes tükrözés távolságtartó transzformáció.", "type": "true-false", "options": [{"id": "81a71129-1c2b-47af-b97f-61871b5f061f", "text": "Igaz", "isCorrect": true}, {"id": "be453731-93a3-49c0-8067-e60f06c320a0", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "a5427eea-947b-4cf7-b873-3c123b3c5ef2", "text": "7. Szerkeszthető-e háromszög 3 cm, 5 cm, 9 cm oldalakkal?", "type": "true-false", "options": [{"id": "ae490dd8-7bef-4273-8579-9763990a2fb3", "text": "Igaz", "isCorrect": false}, {"id": "a279d4b7-ea53-4f1d-a72f-e02a76494437", "text": "Hamis (3+5 < 9)", "isCorrect": true}], "timeLimit": 15}, {"id": "ff546f76-6a17-4c0d-8440-43c3523aa652", "text": "8. Hány fokos szögeket kapunk egy 120°-os szög felezésekor?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "60"}, {"id": "a501cb68-d652-4703-a2ca-2f0981cbe4e2", "text": "9. A rombusz minden oldala egyenlő hosszú.", "type": "true-false", "options": [{"id": "ac859934-f738-41f5-90a9-d1623a5be684", "text": "Igaz", "isCorrect": true}, {"id": "7fa5d35a-821d-4f4d-8591-6f19127509af", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "5575d71d-3d8c-4da0-bbe0-a3e40acd6646", "text": "10. Hol található a tükörtengelyen lévő pont tükörképe?", "type": "multiple-choice", "options": [{"id": "0af6ea0b-9775-4330-8710-b4d286771580", "text": "Önmagában", "isCorrect": true}, {"id": "a691513e-8dfe-450f-8710-1e773acd72a5", "text": "Az origóban", "isCorrect": false}, {"id": "da83f9a4-f25a-42a7-9d1d-f4ddd125b00c", "text": "A tengely végétől 5 cm-re", "isCorrect": false}, {"id": "4ba5a804-8812-43fa-96b4-4c9ab27c1014", "text": "A sík szélén", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('f6d64f9d-a7f3-445e-884b-aa79aa903ca0', '21feff02-016d-46e2-bb9d-c27495133b1b', '67. óra: Témazáró dolgozat értékelése', 'A geometriai témazáró megbeszélése, szerkesztések értékelése és hibajavítás.', 'Matematika', '6. osztály', 'Geometria, tengelyes tükrözés', '[{"id": "955d0b7f-8b65-4bd5-a422-7fdc3db76170", "text": "Mi volt a leggyakoribb hiba a szerkesztési feladatok során?", "type": "multiple-choice", "options": [{"id": "01679c9c-d19a-4b02-8688-b90d198f3de4", "text": "A körző pontatlan használata és a háromszög-egyenlőtlenség figyelmen kívül hagyása", "isCorrect": true}, {"id": "fe2fa555-44d4-4579-8ddb-17ed0f02fdff", "text": "A ceruza színe", "isCorrect": false}, {"id": "6bc4ce21-c99a-410b-8eff-cfa42ef0451c", "text": "A füzet vonalazása", "isCorrect": false}, {"id": "5b41a6f7-e72c-4e06-b714-e61f4924ce10", "text": "A számok leírása", "isCorrect": false}], "timeLimit": 15}, {"id": "648bd398-8226-4b36-965b-14bb1c8a8802", "text": "A szakaszfelező merőleges merőleges a szakaszra és átmegy a felezőpontján.", "type": "true-false", "options": [{"id": "7fb69bfd-d624-496e-87b5-81302bd359d9", "text": "Igaz", "isCorrect": true}, {"id": "6c4646bb-e180-4382-9fd1-b1303a7492c2", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "79b12256-1570-4179-a9bc-3255b551ec7e", "text": "Mennyi a kör átmérője, ha a sugara 10 cm?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "20"}, {"id": "e2999e2a-7ef2-47e1-9ecb-2cf6442b8805", "text": "A tengelyes tükrözés során a síkidom területe nem változik.", "type": "true-false", "options": [{"id": "b855d418-7545-463b-bc8f-48692d19a1b8", "text": "Igaz", "isCorrect": true}, {"id": "58fc73ab-e8cd-4c11-9870-4b84f1d24aa0", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "1a2b1716-e99a-411f-b46f-444361e3bdbc", "text": "Hány szimmetriatengelye van a körnek?", "type": "multiple-choice", "options": [{"id": "8c5ad265-6989-4f07-9bcb-44c6bba8ae27", "text": "Végtelen sok", "isCorrect": true}, {"id": "49f54a89-6609-4031-8ff3-6f772336db0b", "text": "1", "isCorrect": false}, {"id": "8096f312-7abc-400a-bbc8-808dbb14579a", "text": "2", "isCorrect": false}, {"id": "4139e5a7-06bd-43e1-ad26-7586715a04e2", "text": "4", "isCorrect": false}], "timeLimit": 15}, {"id": "7ab2e402-e172-4553-9ba9-2f014600432d", "text": "A pontos vázlatkészítés megkönnyíti a bonyolultabb szerkesztések elvégzését.", "type": "true-false", "options": [{"id": "8301c147-1eaa-49c5-b719-6d9608406269", "text": "Igaz", "isCorrect": true}, {"id": "69af90f6-60e7-4c12-9187-a93ec9787d93", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "3f420fd1-ad9e-4350-b5bd-1e715e5c0258", "text": "Mennyi a háromszög harmadik szöge, ha az első kettő 50° és 70°?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "60"}]'::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('45c8c71b-50cd-4585-b676-b2b6e0fcc2d9', '21feff02-016d-46e2-bb9d-c27495133b1b', '68. óra: Az arány fogalma', 'Az arány fogalma, felírása kettősponttal és törttel, értelmezése hétköznapi példákban.', 'Matematika', '6. osztály', 'Arány, százalék, szöveges feladatok', '[{"id": "4862ae5f-f312-45bd-bbd2-5f59f6553611", "text": "Mit fejez ki két mennyiség aránya?", "type": "multiple-choice", "options": [{"id": "bab95a47-55d7-4950-b638-8095227c1a0f", "text": "Megmutatja, hányszorosa az egyik mennyiség a másiknak (hányadosukat)", "isCorrect": true}, {"id": "936efc71-d38b-4dc9-be4d-b30b6c1b37f1", "text": "Megmutatja a két mennyiség összegét", "isCorrect": false}, {"id": "c0968912-b319-49ee-971b-ef74fd99c8ad", "text": "Megmutatja a két mennyiség szorzatát", "isCorrect": false}, {"id": "b0fc8de6-4a69-499a-9419-6a02ac28161c", "text": "Nem fejez ki semmit", "isCorrect": false}], "timeLimit": 15}, {"id": "a340f81e-71ee-4108-a475-7309d481f371", "text": "Hogyan jelöljük az arányt matematikailag?", "type": "multiple-choice", "options": [{"id": "9d77d4b7-90aa-4095-8c9e-09c0a18bc667", "text": "Kettősponttal (pl. 2 : 3) vagy törttel (2/3)", "isCorrect": true}, {"id": "65753419-b9aa-4675-b7a7-e943cea7ec1a", "text": "Plusz jellel", "isCorrect": false}, {"id": "f0400022-dfc4-4bc2-86de-6a603c506d46", "text": "Csillaggal", "isCorrect": false}, {"id": "10154c7d-9e92-45b7-ab26-014e7143f4da", "text": "Egyenlőségjellel", "isCorrect": false}], "timeLimit": 15}, {"id": "9fd13707-324a-45d0-93b9-9a3a270e0b08", "text": "Ha egy osztályban 10 fiú és 15 lány van, mi a fiúk és lányok számának aránya legegyszerűbb alakban?", "type": "multiple-choice", "options": [{"id": "81f54fe0-5d66-4f08-91dc-d2949a63343e", "text": "2 : 3 (10/15 egyszerűsítve 5-tel)", "isCorrect": true}, {"id": "4310b097-5008-4513-b9e2-33d3802082ab", "text": "1 : 2", "isCorrect": false}, {"id": "17cd85d6-bae0-43d5-9375-dafb191b8f6d", "text": "3 : 2", "isCorrect": false}, {"id": "0295fdbb-3520-4298-855c-3b1582d66889", "text": "10 : 1", "isCorrect": false}], "timeLimit": 15}, {"id": "51327d07-8df9-430b-9e79-62480931ebae", "text": "Az arány a törtekhez hasonlóan egyszerűsíthető és bővíthető.", "type": "true-false", "options": [{"id": "767272bf-663d-486a-9c94-1a7322e7506a", "text": "Igaz", "isCorrect": true}, {"id": "c598f7e3-d73d-4826-a8c5-c95e080956be", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "f7265b25-6385-4b5f-81ca-682eac3ba441", "text": "Mennyi a 4 : 8 arány egyszerűsített alakja?", "type": "multiple-choice", "options": [{"id": "212a2111-772a-4d58-b9b7-76a634536d3d", "text": "1 : 2", "isCorrect": true}, {"id": "842bb939-3f44-4544-9375-a4720340f1dc", "text": "2 : 4", "isCorrect": false}, {"id": "05278ded-6bda-480d-9d35-cb01805d9a91", "text": "1 : 4", "isCorrect": false}, {"id": "49b2c1f9-a37c-4354-90bf-0728890865fc", "text": "4 : 1", "isCorrect": false}], "timeLimit": 15}, {"id": "08b92100-74c5-4ee3-abe0-a0e412121da2", "text": "Ha az arány 3 : 1, az első mennyiség 3-szor akkora, mint a második.", "type": "true-false", "options": [{"id": "7f3fa123-4f6d-4afb-8431-7ec0707a02d7", "text": "Igaz", "isCorrect": true}, {"id": "ccb3a7a2-d3fe-48d5-afda-fa4946a77b2c", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "17343f13-d774-42c5-999d-dfe8a3ad71ef", "text": "Melyik arány egyenlő az 1 : 2 aránnyal?", "type": "multiple-choice", "options": [{"id": "eb74df5a-7c97-4571-9cf5-04c7344c22cd", "text": "5 : 10", "isCorrect": true}, {"id": "65923f8e-8951-4ff4-9651-2e5307865008", "text": "2 : 1", "isCorrect": false}, {"id": "4cb28605-d43d-481f-acf6-69a544fba0db", "text": "3 : 5", "isCorrect": false}, {"id": "f1e70f39-b246-4b62-8e2d-9c516f59c6a0", "text": "4 : 6", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('965217d5-fc02-4030-bd5c-98f9cec1fad4', '21feff02-016d-46e2-bb9d-c27495133b1b', '69. óra: Arányos osztás', 'Adott mennyiség felosztása megadott arányban (pl. 2 : 3 arányban).', 'Matematika', '6. osztály', 'Arány, százalék, szöveges feladatok', '[{"id": "b97e84cd-5ac8-4316-82de-2dafc7961c8e", "text": "Ha 500 Ft-ot elosztunk 2 : 3 arányban, hány egyenlő részre osztjuk először a teljes összeget?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "5"}, {"id": "176848ba-7688-4c77-8b76-503c29b9a157", "text": "Hány Ft a kisebbik rész 500 Ft 2 : 3 arányú felosztásakor? (1 rész = 100 Ft, 2 rész = 200 Ft)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "200"}, {"id": "30b498ab-3644-46d9-b92e-92cdc95178cf", "text": "Hány Ft a nagyobbik rész 500 Ft 2 : 3 arányú felosztásakor? (3 rész = 300 Ft)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "300"}, {"id": "eedd9ec8-d391-4b24-9e84-dc27f2d45fca", "text": "Az arányos osztásnál az arányszámok összege megadja az összes egység (rész) számát.", "type": "true-false", "options": [{"id": "3784e183-9fec-4423-abff-473e8afcb629", "text": "Igaz", "isCorrect": true}, {"id": "218dec51-dba8-4c73-af6b-1de938135658", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "e3a21a66-98c5-4c82-8b3b-5be149364aa0", "text": "Ossz el 30 szem cukorkát 1 : 2 arányban! Hány cukorka a nagyobbik adag?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "20"}, {"id": "153bc1cf-aa2f-4bd1-9d35-80649acb606a", "text": "Ossz el 30 szem cukorkát 1 : 2 arányban! Hány cukorka a kisebbik adag?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "10"}, {"id": "b54ba82f-b250-46ca-901b-bc6c3d0652ff", "text": "Az arányos osztási feladatok ellenőrizhetők a kapott részek összegzésével.", "type": "true-false", "options": [{"id": "8858b1e8-5542-4a78-ab03-a355c6fae85c", "text": "Igaz", "isCorrect": true}, {"id": "1682739d-7288-43a9-a0c5-76c0bd94f9c7", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('b6292d81-2fe9-4a21-bcc2-e4c77621db1b', '21feff02-016d-46e2-bb9d-c27495133b1b', '70. óra: Feladatok megoldása', 'Hétköznapi recept, ötvözet, keverék és arányos osztási feladatok.', 'Matematika', '6. osztály', 'Arány, százalék, szöveges feladatok', '[{"id": "9ccfecad-c48b-4107-aace-bc0ae92ec08a", "text": "Egy habarcs készítéséhez homok és mész kell 4 : 1 arányban. Hány kg homok kell 50 kg habarcshoz?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "40"}, {"id": "5979b1dd-81c5-4cde-a425-4e45b04a162a", "text": "Egy szörp elkészítéséhez szörp és víz kell 1 : 4 arányban. Hány dl szörp kell 10 dl (1 liter) italhoz?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "2"}, {"id": "6e202097-e42c-4bff-b6f5-894e0a511dc2", "text": "Ha két testvér 3 : 5 arányban osztozik 800 Ft-on, a nagyobbik rész 500 Ft.", "type": "true-false", "options": [{"id": "96cec819-602c-41d3-8540-4405f599ac48", "text": "Igaz (800 / 8 = 100, 5 * 100 = 500)", "isCorrect": true}, {"id": "7675f04e-48d9-4b22-ac60-5e6c12cf3dad", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "50322fe7-bf68-4542-a269-2f23638717fa", "text": "Egy téglalap két szomszédos oldalának aránya 2 : 3. Ha a rövidebb oldal 6 cm, hány cm a hosszabb oldal?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "9"}, {"id": "bf6e8874-e3ed-4527-9acf-f41f11b7b7e1", "text": "Melyik állítás igaz az arányos osztásra?", "type": "multiple-choice", "options": [{"id": "99d7bd13-00d4-4ef7-bdcb-a8b358c6b7b8", "text": "A kapott részek aránya megegyezik a megadott aránnyal", "isCorrect": true}, {"id": "5dd967a3-4046-4053-ae60-afb82c995f18", "text": "Minden rész egyenlő nagyságú", "isCorrect": false}, {"id": "28d4c252-b248-4056-96fd-f079c5f23686", "text": "A részek összege kisebb az eredeti mennyiségnél", "isCorrect": false}, {"id": "a2f79ca2-94c8-4a16-a51d-b58e8cd54a93", "text": "Nem lehet kiszámolni", "isCorrect": false}], "timeLimit": 15}, {"id": "21b6917e-eff3-4bcb-bcd2-9ca02a322d50", "text": "Hány g mész kell 50 kg (4:1 arányú) habarcshoz?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "10"}, {"id": "210ae9a5-5879-473d-bb16-3f371b397736", "text": "A receptekben megadott hozzávalók aránya lehetővé teszi tetszőleges adag elkészítését.", "type": "true-false", "options": [{"id": "fce8b606-b94e-49d3-8c1b-36c114082ab5", "text": "Igaz", "isCorrect": true}, {"id": "450d95d0-6eed-4ea9-a4f0-b05ba4e44dde", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;